public function isListeningTo($event)
{
  if (
    $this->isActionEvent($event, 'Gain') ||
    $this->isActionEvent($event, 'Receive') ||
    $this->isActionEvent($event, 'Reap') ||
    $this->isActionEvent($event,'Collect')
  ) {
