methods.plantAdditionalGoods:
public function plantAdditionalGoods()
{
  $player = Players::getActive();
  $fields = $this->getValidFields();
  $sows = [];

  foreach ($fields as $field) {
    $type = $field['crops'][0]['type'];
    $location = $field['type'] == 'fieldCard' ? $field['id'] : 'board';

    $ids = Meeples::createResourceInLocation(
      $type,
      $location,
      $field['pId'],
      $field['x'],
      $field['y'],
      1
    );

    $sows[] = [
      'field' => $field['id'],
      'type' => $type,
      'crops' => Meeples::getMany($ids)->toArray(),
    ];      
