  $payGrain = [
    'type' => NODE_XOR,
    'optional' => false,
    'childs' => [
      [
        'action' => SPECIAL_EFFECT,
        'optional' => false,
        'args' => [
          'cardId' => $this->id,
          'method' => 'eatFieldGrain',
        ],
      ],
      $this->payNode([GRAIN => 1]),
    ],
  ];

  return [
    'type' => NODE_SEQ,
    'optional' => true,
    'childs' => [
      $payGrain,
      [
        'type' => NODE_XOR,
        'childs' => $childs,
      ],
    ],
  ];
}

