public function computeBonusScore()
{
  $player = $this->getPlayer();
  $zones = $player->board()->getAnimalsDropZones();
  Utils::filter($zones, function ($zone) {
    return $zone['type'] == 'stable';
  });
  if (count($zones) > 0) {
    $this->addBonusScoringEntry(count($zones));
  }
