public function computeBonusScore()
{
  $bonus = 0;
  $zones = $this->getPlayer()->board()->getAnimalsDropZones();

  foreach ($zones as $zone) {
    if ($zone['type'] == 'pasture' && count($zone['locations']) >= 3) {
     $bonus += 2;
    }
  }

  if ($bonus > 0) {
    $this->addBonusScoringEntry($bonus);
  }
}

