methods.computeBonusScore:
public function computeBonusScore()
{
  $max = 0;
  $bonusPlayers = [];
  foreach (Players::getAll() as $player) {
    $nbRooms = $player->countRooms();
    if ($nbRooms > $max) {
      $max = $nbRooms;
      $bonusPlayers = [];
    }

    if ($nbRooms == $max) {
      $bonusPlayers[] = $player;
    }
  }

  foreach ($bonusPlayers as $player) {
    $this->addBonusScoringEntry(3, null, $player);
  }
}

