methods.onBuy:
public function onBuy($player)
{
  $zones = $player->board()->getAnimalsDropZonesWithAnimals();
  $freeAnimalSlots = [SHEEP => 0, PIG => 0, CATTLE => 0];
  $numWildcardSlots = 0;

  foreach ($zones as &$zone) {
    // Check cards
    if ($zone['type'] == 'card') {
      // C11_WildlifeReserve
      if (method_exists(PlayerCards::get($zone['card_id']), 'canAcceptAnimal')) {
        foreach ($freeAnimalSlots as $type => &$amt) {
          if (PlayerCards::get($zone['card_id'])->canAcceptAnimal($zone, ['type' => $type])) {
            $amt += 1;
          }
        }
      } elseif ($zone['card_id'] == 'B12_Stockyard') {
        // If empty can take any animal
        if ($zone['animals'] == 0) {
          $numWildcardSlots += 1;
        } else {
          // If already has an animal but less than 3, can take another animal of that type
          foreach ($freeAnimalSlots as $type => &$amt) {
            if ($zone[$type] > 0 && $zone[$type] < 3) {
              $amt += 1;
            }
          }
        }
      } elseif ($zone['card_id'] == 'C86_LivestockFeeder') {
        // Check that enough food AND grain exists (converting grain to food after getting the option is not allowed)
        $playerFood = $player->countReserveResource(FOOD);
        if ($playerFood >= 2) {
          $numWildcardSlots += $zone['capacity'] - $zone['animals'];
        } else {
          $numWildcardSlots += max(0, $zone['capacity'] - $zone['animals'] - (2 - $playerFood));
        }
      } elseif ($zone['card_id'] == 'E86_PenBuilder') {
        $numWildcardSlots += max(0, $zone['capacity'] - $zone['animals']);
      }

    } elseif (isset($zone['constraints']) && $zone['animals'] < $zone['capacity']) {
      // Check constrained zones
      foreach ($zone['constraints'] as $constraint) {
        $freeAnimalSlots[$constraint] += 1;
      }

    } elseif ($zone['animals'] == 0) {
      // If zones are empty, add wildcard
      $numWildcardSlots += 1;

    } elseif ($zone['animals'] < $zone['capacity']) {
      // If slot has animals, add to that type
      foreach ($freeAnimalSlots as $type => &$amt) {
        if ($zone[$type] > 0) {
          $amt += 1;
        }
      }
    }
  }

  Utils::filter($freeAnimalSlots, function ($numAnimals) {
    return $numAnimals > 0;
  });

  if (count($freeAnimalSlots) + $numWildcardSlots >= 3) {
    return $this->payGainNode([FOOD => 2], [SHEEP => 1, PIG => 1, CATTLE => 1]);
  }
}

