public function checkConditions()
{
  $player = $this->getPlayer();
  $vegetable = false;
  $grain = false;
  $empty = false;

  foreach ($player->board()->getFieldsAndCrops() as $field) {
    $grain = $grain || $field['fieldType'] == GRAIN;
