public function computeBonusScore()
{
  $player = $this->getPlayer();
  $bonus = 0;

  $zones = $player->board()->getAnimalsDropZonesWithAnimals();
  foreach ($zones as $zone) {
    if ($zone[CATTLE] >= 1) {
      $bonus+= min($zone[CATTLE], count($zone['locations']));
    }
  }

  if ($bonus != 0) {
    $this->addBonusScoringEntry($bonus);
  }
}

