public function decreaseRoom($player)
{
  $n = 0;
  $player = $this->getPlayer();
  $zones = $player->board()->getAnimalsDropZonesWithAnimals();

  foreach ($zones as &$zone) {
    if (isset($zone['card_id']) && $zone['card_id'] == $this->id) {          
      $n = $zone['capacity'] - $zone['animals'];
      break;
    }
