methods.removeReed:
protected function removeReed(&$args)
{
  if (isset($args['costs']['fees'])) {
    foreach ($args['costs']['fees'] as &$fee) {
      if (isset($fee[REED])) {
        unset($fee[REED]);
        $fee['sources'][] = $this->id;
      }
    }
  }

  foreach ($args['costs']['trades'] as &$trade) {
    if (isset($trade[REED])) {
      unset($trade[REED]);
      $trade['sources'][] = $this->id;
    }
  }
}

