public function onBuy($player)
{
  $n = 0;
  $emptyFields = 0;

  foreach ($player->board()->getSowableFields(null, true) as $field) {
    if ($field['type'] == 'field') {
      $emptyFields++;
    }
  }

  if ($emptyFields >= 2) {$n = 1;}
