public function giveFood()
{
  $player = $this->getPlayer();
  $flow = [];
  foreach (Players::getAll() as $pId2 => $player2) {
    if ($this->pId == $pId2) {
      continue;
    }
    $flow[] = $this->gainNode([FOOD => 1], $pId2);
