methods.onBuy:
public function onBuy($player)
{
  $fields = $player->board()->getSowableFields(null, true);
  $sows = [];

  if (count($fields) != 0) {
    $woodfieldPlanted = false;
    foreach ($fields as $fId => $field) {
      $location = $field['type'] == 'fieldCard' ? $field['id'] : 'board';

      // Check if D75_WoodField already received a stone
      if ($location == 'D75_WoodField') {
        if ($woodfieldPlanted) {
          continue;
        } else {
          $woodfieldPlanted = true;
        }
      }

      $ids = Meeples::createResourceInLocation(STONE, $location, $field['pId'], $field['x'], $field['y'], 1);

      $sows[] = [
        'field' => $field,
        'seed' => null,
        'crops' => Meeples::getMany($ids)->toArray(),
      ];
    }
    // Notify
    Notifications::sow($player, $sows, true);
  }
}

