methods.onPlayerAfterImprovement:
public function onPlayerAfterImprovement($player, $event)
{
  $card = PlayerCards::get($event['cardId']);
  $triggers = [
    'Major_Fireplace1',
    'Major_Fireplace2',
    'Major_CookingHearth1',
    'Major_CookingHearth2',
    'Major_ClayOven',
    'Major_StoneOven',
    'E63_IronOven',
    'E64_SimpleOven',
    'D59_EarthOven'
  ];

  if (in_array($card->getId(), $triggers)) {
    $n = Meeples::getResourcesOnCard($this->id, null, WOOD)->count();
    if ($n > 4) {
      $n = 4;
    }

    $childs = [];
    for ($i = 1; $i <= $n; $i++) {
      $childs[] = [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'receiveWood',
          'args' => [$i]
        ]
      ];
    }

    $wolf = $this->checkWolf($player);
    if ($wolf != []) {
      return [
        'type' => NODE_SEQ,
        'optional' => true,
        'childs' => [
          [
            'type' => NODE_XOR,
            'childs' => $childs,
          ],
          $wolf,
        ]
      ];
    }      

    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => $childs,
    ];
  }
}

