    $childs[] = [
      'action' => SPECIAL_EFFECT,
      'args' => [
        'cardId' => $this->id,
        'method' => 'breedAnimal',
        'args' => [$type],
      ],
    ];
  }

  return [
    'type' => NODE_SEQ,
    'childs' => [
      $this->flagCardNode(),
      $this->payNode([GRAIN => 1]),
      [
        'type' => NODE_XOR,
        'childs' => $childs,
      ],
    ],
  ];
}

