methods.removeWood:
protected function removeWood(&$args, $nb)
{
  foreach ($args['costs']['trades'] as &$trade) {
    if (isset($trade[WOOD])) {
      $trade[WOOD] -= $nb;
      if ($trade[WOOD] <= 0) {
        unset($trade[WOOD]);
      }
      $trade['sources'][] = $this->id;
    }
  }
}

methods.onPlayerComputeCostsStables:
public function onPlayerComputeCostsStables($player, &$args)
{
  if($this->getExtraDatas('stables') === null){
    $this->setExtraDatas('stables',count($player->board()->getStables()));
  }
  if($this->getExtraDatas('stables') >= 3){
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false); 
  }
  else{
    $third = 3-$this->getExtraDatas('stables');
    $fourth = 4-$this->getExtraDatas('stables');
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $third]);
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $fourth]);
  }
}

