  else{
    $thirteenth = 13-$this->getExtraDatas('fences');
    $fourteenth = 14-$this->getExtraDatas('fences');
    $fifteenth = 15-$this->getExtraDatas('fences');
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $thirteenth]);
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $fourteenth]);
    Utils::addBonus($args['costs'], [WOOD => -1], $this->id, false, ['minNumRooms' => $fifteenth]);
  }
}

