methods.getValidAnimals:
public function getValidAnimals()
{
  $player = Players::getActive();
  $zones = $player->board()->getAnimalsDropZonesWithAnimals();
  $valid = [];

  foreach ([SHEEP, PIG, CATTLE] as $type) {
    // Search zone of same animal type with an empty slot
    $sameFound = false;
    foreach ($zones as &$zone) {
      if ($zone['type'] == 'card' && method_exists(PlayerCards::get($zone['card_id']), 'canAcceptAnimal')) {
        if (PlayerCards::get($zone['card_id'])->canAcceptAnimal($zone, ['type' => $type])) {
          $sameFound = true;
          $valid[] = $type;
          break;
        }
      } elseif ($zone['animals'] < $zone['capacity'] && $zone[$type] > 0) {
        $sameFound = true;
        $valid[] = $type;
        break;
      }
    }

    // Now search any zone with a free spot
    if (!$sameFound) {
      foreach ($zones as &$zone) {
        if ($zone['animals'] == 0 && in_array($type, $zone['constraints'] ?? ANIMALS)) {
          $valid[] = $type;
          break;
        }
      }
    }
  }

  return $valid;
}

methods.computeSpecialScore:
public function computeSpecialScore($scores)
{
  foreach ($scores as $pId => $score) {
    $bonus = 0;

    if ($pId != $this->getPlayer()->getId()) {
      continue;
    }

    foreach ($score as $type => $values) {
      if (!in_array($type, ['fields', 'pastures', 'grains', 'vegetables', 'sheeps', 'pigs', 'cattles', 'stables'])) {
        continue;
      }

      if (isset($values['entries'])) {
        foreach ($values['entries'] as $entry) {
          if ($entry['score'] == 4) {
            $bonus++;
          }
        }
      }
    }

    if ($bonus > 0) {
      $this->addBonusScoringEntry($bonus, null, Players::get($pId));
    }
  }
}

