public function onPlayerComputeCardCosts($player, &$args)
{
  if (!in_array($args['card']->getType(), [MAJOR, MINOR])) {
    return;
  }

  foreach ($args['costs']['trades'] as $trade) {
    if (isset($trade[WOOD])) {
      $trade[WOOD] -= 2;
      if ($trade[WOOD] <= 0) {
        unset($trade[WOOD]);
      }
      $trade[FOOD] = ($trade[FOOD] ?? 0) + 1;
      $trade['sources'][] = $this->id;
      $args['costs']['trades'][] = $trade;
    }
  }
}

