methods.getGoods:
public function getGoods($n)
{
  $player = $this->getPlayer();
  $goods = array_reverse(Meeples::getResourcesOnCard($this->id)->toArray());
  $meeples = [];

  $i = 0;
  foreach ($goods as $good) {
    if ($i == $n) {
      break;
    }
    Meeples::receiveResource($player, $good);
    $meeples[] = $good;
    $i++;
  }

  Notifications::receiveResources($player, $meeples);

  $event['meeples'] = $meeples;

  if ($player->hasPlayedCard('E103_Wolf')) {
    $wolf = PlayerCards::get('E103_Wolf');
    Engine::insertAsChild($wolf->onPlayerAfterObtain($player, $event));
  }
}

