  }

  return [
    'type' => NODE_SEQ,
    'optional' => true,
    'childs' => [
      $this->unflagCardNode(),
      $this->payNode([WOOD => $wood-5]),
      [
        'type' => NODE_XOR,
        'childs' => $actions,
      ],
      $this->flagCardNode(),
    ],
  ];      
}

