public function computeBonusScore()
{
  $max = 0;
  $bonusPlayers = [];
  foreach (Players::getAll() as $player) {
    $fieldVegetables = $player->board()->getGrowingCrops(VEGETABLE)->count();

    if ($fieldVegetables > $max) {
      $max = $fieldVegetables;
      $bonusPlayers = [];
    }

    if ($fieldVegetables == $max) {
      $bonusPlayers[] = $player;
    }
  }

  foreach ($bonusPlayers as $player) {
    $this->addBonusScoringEntry(2, null, $player);
  }
}

