  if ($args['actionCardId'] != 'D13_Trowel') {
    return;
  }
  if ($player->getRoomType() == 'roomWood') {
    foreach ($args['costs']['trades'] as &$trade) {
      $trade[STONE] = 1;
      $trade[FOOD] = 1;
      $trade['sources'][] = $this->id;
    }
    foreach ($args['costs']['fees'] as &$fee) {
      $fee[REED] = $player->countRooms();
      $fee['sources'][] = $this->id;
    }
  } else {
    foreach ($args['costs']['trades'] as &$trade) {
      $trade[STONE] = 1;
      $trade['sources'][] = $this->id;
    }
    foreach ($args['costs']['fees'] as &$fee) {
      unset($fee[REED]);
      $fee['sources'][] = $this->id;
    }
  }
}

