methods.getGains:
public function getGains($event)
{
  $meeples = [CLAY => 0, REED => 0, STONE => 0, FOOD => 0, SHEEP => 0, PIG => 0, CATTLE => 0, GRAIN => 0, VEGETABLE => 0];
  foreach ($event['meeples'] as $meeple) {
    $type = $meeple['type'];
    if (\array_key_exists($type, $meeples)) {
      $meeples[$type]++;
    }
  }

  foreach ($meeples as $type => $n) {
    if ($n >= 3) {
      return true;
    }
  }

  return false;
}

