methods.getGains:
public function getGains($event)
{
  $meeples = [WOOD => 0, CLAY => 0, REED => 0, STONE => 0];
  foreach ($event['meeples'] as $meeple) {
    $type = $meeple['type'];
    if (\array_key_exists($type, $meeples)) {
      $meeples[$type]++;
    }
  }

  $gains = [];
  foreach ($meeples as $type => $n) {
    if ($n >= 4) {
      $gains[$type] = 1;
    }
  }

  if (!empty($gains)) {
    $gains[FOOD] = 1;
  }

  return $gains;
}

