public function computeBonusScore()
{

  $player = $this->getPlayer();
  $bonus = 0;

  foreach ($player->getCards(MAJOR, true) as $major) {
    if (in_array(
      $major->getId(),
      ['Major_ClayOven', 'Major_StoneOven', 'Major_Joinery', 'Major_Pottery', 'Major_Basket']
    )) {
      $bonus++;
    }
  }

  $bonusMap = [0, 0, 0, 2, 5, 8];
  $bonuss = $bonusMap[$bonus] ?? 8;
  $this->addBonusScoringEntry($bonuss);
}

public function computeBonusScore()
{
  $player = $this->getPlayer();

  $grain = $player->countReserveResource(GRAIN) + 
    $player->board()->getGrowingCrops(GRAIN)->count();    
  $vegetables = $player->countReserveResource(VEGETABLE) + 
    $player->board()->getGrowingCrops(VEGETABLE)->count();

  $pairs = min($grain, $vegetables);
  $bonus = ceil($pairs / 2);

  if ($bonus > 0) {
    $this->addBonusScoringEntry($bonus);
  }
}

