methods.calcTradeReplace:
function calcTradeReplace($trade)
{
  $replacement = [];
  $resList = [WOOD, CLAY, STONE, REED];
  for ($i = 1; $i < (1 << 4); $i++) {
    $res = [];
    for ($j = 0; $j < 4; $j++) {
      if ($i & (1 << $j)) {
        $res[] = $resList[$j];
      }
    }
    $copy = $trade;
    $flag = false;
    foreach ($res as $r) {
      if (isset($copy[$r])) {
        $flag = true;
        $copy[$r] -= 1;
        if ($copy[$r] <= 0) {
          unset($copy[$r]);
        }
        if (isset($copy[FOOD])) {
          $copy[FOOD] += 1;
        } else {
          $copy[FOOD] = 1;
        }
      }
    }
    if ($flag) {
      $copy['sources'][] = $this->id;
      $replacement[] = $copy;
    }
  }
  return $replacement;
}

