  $goods = Meeples::getResourcesOnCard($this->id);
  $left = [];
  $n = 0;
  foreach ($goods as $good) {
    $left[] = $good['type'];
  }
  $left = array_reverse($left);
  $choices = [];
  $bonus = [];
  for ($i = 0; $i < count($left); $i++) {
    $bonus[] = $left[$i];
    $choices[] = self::buildChoice($bonus);
  }
  Utils::addBonusChoices($args['costs'], $choices, $this->id, true);
}

