    if ($vegetables  > $max) {
      $max = $vegetables ;
      $bonusPlayers = [];
    }
    if ($vegetables  == $max) {
      $bonusPlayers[] = $player;
    }
  }
  foreach ($bonusPlayers as $player) {
    $this->addBonusScoringEntry(3, null, $player);
  }
}

