  $wood = 0;
  $stone = 0;
  foreach ($event['sows'] as $sow) {
    if ($sow['type'] == GRAIN) {
      $grain = 1;
    }
    elseif ($sow['type'] == VEGETABLE) {
      $vegetable = 1;
    }
    elseif ($sow['type'] == WOOD) {
      $wood = 1;
    }
    elseif ($sow['type'] == STONE) {
      $stone = 1;
    }
  }
  $totals=$grain + $vegetable + $wood + $stone;
  if ($totals>0)
  return $this->gainNode([FOOD => $totals]);
}

