methods.onBuy:
public function onBuy($player)
{
  $spaces = $this->getSpaces();
  if ($spaces == []) {
    return;
  }

  $childs = [];
  $take = [];
  $take[WOOD] = [];
  $take[CLAY] = [];
  $take[REED] = [];
  $take[STONE] = [];
  foreach ($spaces as $space) {
    $types = [];
    foreach (Meeples::getResourcesOnCard($space->getId()) as $meeple) {
      if (!in_array($meeple['type'], $types)) {
        $types[] = $meeple['type'];
      }
    }

    foreach ($types as $type) {
      $take[$type][] = [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'takeFromSpace',
          'args' => [$space->getId(), $type],
        ],
      ];
      $childs[] = [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'takeFromSpace',
          'args' => [$space->getId(), $type],
        ],
      ];
    }
  }
  $types = [WOOD,CLAY,REED,STONE];
  $typeold = [];
  foreach($types as $type){
    $typeold[] = $type;
    foreach($take[$type] as $takeone){
    foreach($types as $type2){
      if(!in_array($type2,$typeold)){
        foreach($take[$type2] as $taketwo){
        $childs[] = [
          'type' => NODE_SEQ,
          'optional' => false,
          'childs' => [$takeone,$taketwo],
        ];}
      }
    }}
  }
  return [
    'type' => NODE_XOR,
    'optional' => false,
    'childs' => $childs,
  ];
}

methods.getSpaces:
public function getSpaces()
{
  $valid = [];

  foreach ([WOOD, CLAY, REED, STONE] as $type) {
