  /*
  foreach ($opts as $res) {
        $newTrade2 = [];
        $newTrade2[$res] = 1;
        $newTrade2['sources'][] = $this->id;
        $newTrades[] = $newTrade2;
      }*/

  if(!$flag){
    $args['costs']['trades'] = array_merge($args['costs']['trades'], $newTrades);
     //$args['costs']['trades'] = $newTrades;
  }
}

