methods.reduceImprovementCosts:
private function reduceImprovementCosts(&$args)
{
    $resourcesOnCard = Meeples::getResourcesOnCard($this->id, null);

    if (!$resourcesOnCard->empty()) {
        // 统计每种资源在卡牌上的数量
        $resourceCounts = [];
        foreach ($resourcesOnCard as $meeple) {
            $resourceType = $meeple['type'];
            if (!isset($resourceCounts[$resourceType])) {
                $resourceCounts[$resourceType] = 0;
            }
            $resourceCounts[$resourceType]++;
        }

        // 调整成本中的交易部分
        if (isset($args['costs']['trades'])) {
            foreach ($args['costs']['trades'] as &$trade) {
                foreach ($resourceCounts as $resourceType => $count) {
                    if (isset($trade[$resourceType])) {
                        $trade[$resourceType] = max(0, $trade[$resourceType] - $count);
                        if ($trade[$resourceType] == 0) {
                            unset($trade[$resourceType]);
                        }
                        if (empty($trade)) {
                            break;
                        }
                    }
                }
            }
        }
    }
}

methods.reduceCosts:
private function reduceCosts(&$args)
{
    $resourcesOnCard = Meeples::getResourcesOnCard($this->id, null);

    if (!$resourcesOnCard->empty()) {
        // 统计每种资源在卡牌上的数量
        $resourceCounts = [];
        foreach ($resourcesOnCard as $meeple) {
            $resourceType = $meeple['type'];
            if (!isset($resourceCounts[$resourceType])) {
                $resourceCounts[$resourceType] = 0;
            }
            $resourceCounts[$resourceType]++;
        }

        // 减少成本
        foreach ($resourceCounts as $resourceType => $count) {
            Utils::addBonus($args['costs'], [$resourceType => -$count], $this->id);
        }
    }
}

