    public function getGains($event)
  {
    $meeples = [WOOD => 0, CLAY => 0, REED => 0, STONE => 0, FOOD => 0, SHEEP => 0, PIG => 0, CATTLE => 0];
    foreach ($event['meeples'] as $meeple) {
      $type = $meeple['type'];
      if (\array_key_exists($type, $meeples)) {
        $meeples[$type]++;
      }
    }

    $gains = [];
    foreach ($meeples as $type => $n) {
      if ($n >= 1) {
        $gains[$type] = 1;
      }
    }
    return $gains;
  }

