methods.onPlayerAfterConstruct:
public function onPlayerAfterConstruct($player, $event)
{
    // 检查玩家是否建造了至少一间房
    if (isset($event['rooms']) && !empty($event['rooms'])) {
        $n = count($event['rooms']); // 新建的房间数量
        $buildingResources = [WOOD, CLAY, REED, STONE];
        $availableResources = [];

        foreach ($buildingResources as $res) {
            $resources = Meeples::getReserveResource($player->getId(), $res);
            if (!$resources->empty()) {
                $availableResources[] = $res;
            }
        }

        // 提供给玩家可选动作，每间房一次
        if (!empty($availableResources)) {
            $flow = [
                'type' => NODE_SEQ,
                'optional' => true,
                'childs' => [],
            ];

            for ($i = 0; $i < $n; $i++) {
                $childs = [];
                foreach ($availableResources as $resource) {
                    $childs[] = [
                        'type' => NODE_SEQ,
                        'childs' => [
                            $this->payNode([$resource => 1]),
                            [
                                'action' => SPECIAL_EFFECT,
                                'args' => [
                                    'cardId' => $this->id,
                                    'method' => 'addResourceToCard',
                                    'args' => [$resource],
                                ],
                            ],
                        ],
                    ];
                }

                $flow['childs'][] = [
                    'type' => NODE_XOR,
                    'optional' => true,
                    'customDescription' => clienttranslate('你可以将一个建筑资源放在精简建筑师上'),
                    'childs' => $childs,
                ];
            }

            return $flow;
        }
    }

    return null;
}

