methods.onBuy:
 public function onBuy($player)
{
  if (Globals::getTurn() <= 7) {
      $clays=$player->countReserveResource(CLAY);
      $reeds=$player->countReserveResource(REED);
      if ($clays>0 && $reeds==0)
        return $this->gainNode([CLAY=>$clays]);
      elseif ($clays==0 && $reeds>0)
        return $this->gainNode([REED=>$reeds]);
      elseif ($clays>0 && $reeds>0)    
        return [
          'type' => NODE_XOR,
          'optional' => true,
          'childs' => [
            $this->gainNode([CLAY =>$clays]),
            $this->gainNode([REED =>$reeds]),
          ]
       ];
  }
}

methods.onPlayerImmediatelyAfterImprovement:
public function onPlayerImmediatelyAfterImprovement($player, $event)
{
  $card = PlayerCards::get($event['cardId']);
  $costs = $card->getBaseCostsWithFee(true);

  if ($costs == []) {
    return;
  }

  $childs = [];

  foreach ($costs as $cost) {
    if (isset($cost['stable']) || $cost == []) {
      continue;
    }
    $childs[] = $this->gainNode($cost);
  }

  if ($childs != []) {
    return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [
        $this->flagCardNode(),
        [
          'type' => NODE_XOR,
          'childs' => $childs,
        ]
      ]
    ];
  }
}

