methods.actEatFieldCrop:
public function actEatFieldCrop($zones)
{
  if (!$this->isFlagged()) {
    return;
  }
  if (count($zones) != 1) {
    throw new \BgaVisibleSystemException('Select only one field');
  }
  $zone = $zones[0];
  $args = $this->argsEatFieldCrop();
  if (!in_array($zone, $args['sources'])) {
    throw new \BgaVisibleSystemException('Invalid field(s)');
  }
  if($zone['fieldType'] != VEGETABLE && $zone['fieldType'] != GRAIN) { 
    throw new \BgaVisibleSystemException('Select a crop field');
  }
  else {
    $food = $zone['fieldType'] == VEGETABLE ? 3 : 2;
  }

  // $this->setExtraDatas('food', $food);
  // print_r($this->getExtraDatas('food'));
  $meeples = array($zone['crops'][0]);
  Meeples::deleteResources($meeples);
  $locations = array($zone['uid']);
  Notifications::payResourcesFromFields($this->getPlayer(), $meeples, $this->name,$locations);
  $player = $this->getPlayer();//Players::getActive();
  $created = $player->createResourceInReserve(FOOD, $food);
  Notifications::gainResources($player, $created);
  // return ;
}

