public function isBuyable($player, $ignoreResources = false, $args = [])
{
  $empty33 = false;
  $empty53 = false;
  $empty73 = false;
  $surr33 = 4;
  $surr53 = 4;
  $surr73 = 4;

  foreach($player->board()->getFreeZones() as $zone) {
    if($zone['x']==3 && $zone['y']==3)
    {
      $empty33 = true;
    }

    if($zone['x']==5 && $zone['y']==3)
    {
      $empty53 = true;
    }

    if($zone['x']==7 && $zone['y']==3)
    {
      $empty73 = true;
    }

    if(($zone['x']==3 && $zone['y']==1) ||
        ($zone['x']==3 && $zone['y']==5) ||
        ($zone['x']==5 && $zone['y']==3) ||
        ($zone['x']==1 && $zone['y']==3)){
        $surr33 = $surr33 - 1;
      }

      if(($zone['x']==5 && $zone['y']==1) ||
      ($zone['x']==5 && $zone['y']==5) ||
      ($zone['x']==3 && $zone['y']==3) ||
      ($zone['x']==7 && $zone['y']==3)){
      $surr53 = $surr53 - 1;
    }

    if(($zone['x']==7 && $zone['y']==1) ||
      ($zone['x']==7 && $zone['y']==5) ||
      ($zone['x']==5 && $zone['y']==3) ||
      ($zone['x']==9 && $zone['y']==3)){
      $surr73 = $surr73 - 1;
    }
  }

  if (($empty33 == false || $surr33 < 4)&&($empty53 == false || $surr53 < 4)&&($empty73 == false || $surr73 < 4))
  {
    return false;
  }

  return parent::isBuyable($player, $ignoreResources, $args);
