public function isListeningTo($event)
{
  // 获取当前回合数
  $turn = \AGR\Core\Globals::getTurn();

  // 季节对应的回合
  $seasonRounds = [
      1 => [1,2,3,4],
      2 => [5,6,7],
      3 => [8,9],
      4 => [10,11],
      5 => [12,13],
      6 => [14],
  ];

  // 季节对应的所有行动格ID（你需要根据你游戏的实际ID填写）
  $seasonActionCards = [
      1 => ['ActionGrainUtilization', 'ActionMajorImprovement', 'ActionSheepMarket', 'ActionFencing'],
      2 => ['ActionWishChildren', 'ActionWesternQuarry', 'ActionHouseRedevelopment'],
      3 => ['ActionPigMarket', 'ActionVegetableSeeds'],
      4 => ['ActionCattleMarket', 'ActionEasternQuarry'],
      5 => ['ActionCultivation', 'ActionUrgentWishChildren'],
      6 => ['ActionFarmRedevelopment'],
  ];

  // 找到当前季节
  $season = null;
  foreach ($seasonRounds as $s => $rounds) {
      if (in_array($turn, $rounds)) {
          $season = $s;
          break;
      }
  }
  if ($season === null) return false;

  // 判断玩家是否用的是本季节的行动格
  return $this->isActionEvent($event, 'PlaceFarmer') &&
      isset($event['actionCardId']) &&
      in_array($event['actionCardId'], $seasonActionCards[$season]);
}

