methods.isListeningTo:
public function isListeningTo($event)
{
  if($this->isDuringActionEvent($event, 'Gain') ||
    $this->isDuringActionEvent($event, 'Receive') ||
    $this->isDuringActionEvent($event, 'Collect')){
    return true;
  }
  $player = $this->getPlayer();
  if (!$player->hasPlayedCard($this->id)) {
    return false;
  }
  if ($this->isActionEvent($event, 'Exchange')) {
    //print_r($event);
    $this->checkPigIsConverted($event);
    return false;
  }
  $n = $this->getExtraDatas('E53Converted') ?? 0;
  return $this->isAnytime($event) && $n > 0;
}

methods.onPlayerAtAnytime:
public function onPlayerAtAnytime($player, $event)
{
  $n = $this->getExtraDatas('E53Converted') ?? 0;
  if ($n > 0) {
    for ($i = 1; $i <= $n; $i++) {
       $childpay = $this->payGainNode([PIG => $i], [FOOD => $i*4], null, false);
       if($player->hasPlayedCard('E85_MasterTanner')){
         $childall = [
           'type' => NODE_SEQ,
           'optional' => false,
           'childs' => [
             $childpay,
             [
               'action' => SPECIAL_EFFECT,
               'args' => [
                 'cardId' => 'E85_MasterTanner',
                 'method' => 'increaseCattleOrPigCooked',
                 'args' => [$i],
               ],
             ],
           ],
         ];
         $childs[] = $childall;
       }
       else{
        $childs[] = $childpay;
       } 
    }
    $child = [
      'type' => NODE_XOR,
      'optional' => false,
      'childs' => $childs,
    ];
    return [
      'type' => NODE_SEQ,
      'childs' => [
        $this->unflagCardNode('E53Converted'),
        $child,
      ],
    ];
  }
}

methods.checkPigIsConverted:
public function checkPigIsConverted($event)
{
  $trades = $event['trades'];
  $exchanges = $event['exchanges'];
  $count = 0;

  foreach ($trades as $tradeIndex) {
    if (is_array($tradeIndex) && $tradeIndex['source'] == 'discard') {
      continue;
    }
    $exchange = $exchanges[$tradeIndex] ?? null;

    if ($exchange) {
      $isWoodExchange = false;
      foreach ($exchange['to'] as $resource => $amount) {
        if ($resource == PIG) {
          $isWoodExchange = true;
          break;
        }
      }
      if ($isWoodExchange) {
        $count++;
      }
    }
  }
  //print($count);
  if ($count >= 0) {
    $this->setExtraDatas('E53Converted', $count);
  }
}

methods.onPlayerObtain:
public function onPlayerObtain($player, $event)
{
  //return;
  if(!array_key_exists('meeples',$event)){
    return;
  }
  $meeples = $event['meeples'];
  $n = 0;
  $ids = $this->getExtraDatas('ids');
  if($ids==null){
    $ids = [];
  }
  foreach ($meeples as $meeple) {
    if ($meeple['type'] == PIG && !in_array($meeple['id'],$ids)) {
      $n++;
       $ids[] = $meeple['id'];
    }
  }
  if ($n > 0) {
    for ($i = 1; $i <= $n; $i++) {
       $childpay = $this->payGainNode([PIG => $i], [FOOD => $i*4], null, false);
       if($player->hasPlayedCard('E85_MasterTanner')){
         $childall = [
           'type' => NODE_SEQ,
           'optional' => false,
           'childs' => [
             $childpay,
             [
               'action' => SPECIAL_EFFECT,
               'args' => [
                 'cardId' => 'E85_MasterTanner',
                 'method' => 'increaseCattleOrPigCooked',
                 'args' => [$i],
               ],
             ],
           ],
         ];
         $childs[] = $childall;
       }
       else{
        $childs[] = $childpay;
       } 
    }
    $child = [
      'type' => NODE_XOR,
      'optional' => false,
      'childs' => $childs,
    ];
    $setIds = [
        'action' => SPECIAL_EFFECT,
        'args' => [
          'cardId' => $this->id,
          'method' => 'setIds',
          'args' => [$ids],
        ]
      ];
     return [
      'type' => NODE_SEQ,
      'optional' => true,
      'childs' => [$child,
       $setIds,],
    ];
  }
}

methods.onPlayerAfterImprovement:
public function onPlayerAfterImprovement($player, $event)
{
  if ($event['cardId'] == 'E54_Contraband') {
    return;
  }

  $card = PlayerCards::get($event['cardId']);
  $costs = $card->getBaseCostsWithFee();
  $resources = [];

  if ($costs == []) {
    return;
  }

  foreach ($costs as $cost) {
    foreach ([WOOD, CLAY, REED, STONE] as $resType) {
      if (isset($cost[$resType]) && !in_array($resType, $resources)) {
        $resources[] = $resType;
      }
    }
  }

  $childs = [];

  foreach ($resources as $resType) {
    $childs[] = $this->payGainNode([$resType => 1], [FOOD => 3], null, false);
  }

  if ($childs != []) {
    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => $childs,
    ];
  }
}

