methods.getGains:
private function getGains($event)
{
    $buildingResources = [WOOD, CLAY, REED, STONE];
    $collectedResources = [];

    // 遍历收集到的资源，统计建筑资源的数量
    foreach ($event['meeples'] as $meeple) {
        $type = $meeple['type'];
        if (in_array($type, $buildingResources)) {
            if (!isset($collectedResources[$type])) {
                $collectedResources[$type] = 0;
            }
            $collectedResources[$type]++;
        }
    }

    // 如果收集到了建筑资源，给予玩家额外的对应资源
    $gains = [];
    foreach ($collectedResources as $type => $count) {
        if ($count > 0) {
            $gains[$type] = 1;
            // 假设每次只触发一次，针对一个资源类型
            break;
        }
    }

    return $gains;
}

