methods.onBuy:
public function onBuy($player) {
  $c = $player->getExchangeResources()[CATTLE];
  $n = intdiv($c, 2);

  $childs = [];
  for ($i = 1; $i <= $n; $i++) {
    $childs[] = $this->payGainNode([GRAIN => $i], [SCORE => 2*$i], null, false);
  }

  if ($n > 0) {
    return [
      'type' => NODE_XOR,
      'optional' => true,
      'childs' => $childs,
    ];
  }
}

