  }
  if($this->isActionEvent($event, 'Exchange')) {
    $this->checkCattleOrPigCooked($event);
    return false;
  }
  $n = $this->getExtraDatas('E85Cooked') ?? 0;
  return $this->isAnytime($event) && $n > 0;
}

